// Minimal meta-schema checker: validates a user schema against a meta-schema,
// resolving $ref via an $id registry + local JSON pointers; $recursiveRef /
// $dynamicRef and unresolvable refs are treated as valid.
import { META4, META6, META7, META2019, META2020 } from '/output/lib/meta/schemas.mjs';

function buildRegistry(root) {
  const reg = new Map();
  const walk = (node, base) => {
    if (Array.isArray(node)) { node.forEach((n) => walk(n, base)); return; }
    if (node && typeof node === 'object') {
      let b = base;
      const id = node.$id || node.id;
      if (typeof id === 'string') {
        b = new URL(id, base || 'https://x.invalid/').href;
        if (!reg.has(b)) reg.set(b, node);
        if (!reg.has(id)) reg.set(id, node);
      }
      for (const v of Object.values(node)) walk(v, b);
    }
  };
  walk(root, null);
  return reg;
}

function resolvePointer(doc, pointer) {
  let cur = doc;
  for (const raw of pointer.split('/').slice(1)) {
    const tok = raw.replace(/~1/g, '/').replace(/~0/g, '~');
    if (cur == null || typeof cur !== 'object' || !(tok in cur)) return undefined;
    cur = cur[tok];
  }
  return cur;
}

const isNum = (v) => typeof v === 'number';
const isInt = (v) => isNum(v) && Number.isInteger(v);
const isStr = (v) => typeof v === 'string';
const isBool = (v) => typeof v === 'boolean';
const isArr = Array.isArray;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

function pyEqual(a, b) {
  if (isBool(a) || isBool(b)) {
    if (isNum(a) || isNum(b)) return Number(a) === Number(b);
    return a === b;
  }
  if (isNum(a) && isNum(b)) return a === b;
  if (typeof a !== typeof b) return false;
  if (isArr(a) && isArr(b)) return a.length === b.length && a.every((x, i) => pyEqual(x, b[i]));
  if (isObj(a) && isObj(b)) {
    const ka = Object.keys(a), kb = Object.keys(b);
    return ka.length === kb.length && ka.every((k) => k in b && pyEqual(a[k], b[k]));
  }
  return a === b;
}

function makeValidator(root) {
  const registry = buildRegistry(root);
  const errors = [];

  function resolveRef(ref, doc, base) {
    // returns {node, doc, base} or undefined
    const [uriPart, frag] = ref.split('#');
    let targetDoc = doc, targetBase = base;
    if (uriPart) {
      const abs = base ? new URL(uriPart, base).href : uriPart;
      const found = registry.get(abs) || registry.get(uriPart);
      if (!found) return undefined;
      targetDoc = found; targetBase = abs;
    }
    if (frag === undefined || frag === '') return { node: targetDoc, doc: targetDoc, base: targetBase };
    if (frag.startsWith('/')) {
      const node = resolvePointer(targetDoc, frag);
      return node === undefined ? undefined : { node, doc: targetDoc, base: targetBase };
    }
    return undefined; // plain-name fragments unresolvable -> valid
  }

  function validate(instance, schema, doc, base, depth) {
    if (depth > 200) return; // recursion guard
    if (schema === true) return;
    if (schema === false) { errors.push('false schema'); return; }
    if (!isObj(schema)) return;

    if (typeof schema.$ref === 'string') {
      const r = resolveRef(schema.$ref, doc, base);
      if (r) validate(instance, r.node, r.doc, r.base, depth + 1);
      // drafts <=7: ignore siblings
      if (root !== META2019 && root !== META2020) return;
    }

    const t = schema.type;
    if (t !== undefined) {
      const types = isArr(t) ? t : [t];
      const ok = types.some((ty) =>
        ty === 'number' ? isNum(instance) :
        ty === 'integer' ? isInt(instance) :
        ty === 'string' ? isStr(instance) :
        ty === 'boolean' ? isBool(instance) :
        ty === 'array' ? isArr(instance) :
        ty === 'object' ? isObj(instance) :
        ty === 'null' ? instance === null : false);
      if (!ok) { errors.push(`type ${JSON.stringify(t)}`); return; }
    }
    if (schema.enum !== undefined && isArr(schema.enum)) {
      if (!schema.enum.some((e) => pyEqual(e, instance))) errors.push('enum');
    }
    if (isObj(instance)) {
      if (schema.properties !== undefined && isObj(schema.properties)) {
        for (const [k, sub] of Object.entries(schema.properties)) {
          if (k in instance) validate(instance[k], sub, doc, base, depth + 1);
        }
      }
      if (schema.patternProperties !== undefined && isObj(schema.patternProperties)) {
        for (const [pat, sub] of Object.entries(schema.patternProperties)) {
          for (const [k, v] of Object.entries(instance)) {
            if (new RegExp(pat).test(k)) validate(v, sub, doc, base, depth + 1);
          }
        }
      }
      if (schema.additionalProperties !== undefined && isObj(schema.properties)) {
        const covered = new Set(Object.keys(schema.properties));
        const pats = isObj(schema.patternProperties) ? Object.keys(schema.patternProperties) : [];
        for (const [k, v] of Object.entries(instance)) {
          if (covered.has(k)) continue;
          if (pats.some((p) => new RegExp(p).test(k))) continue;
          validate(v, schema.additionalProperties, doc, base, depth + 1);
        }
      }
      if (schema.dependencies !== undefined && isObj(schema.dependencies)) {
        for (const [k, dep] of Object.entries(schema.dependencies)) {
          if (!(k in instance)) continue;
          if (isArr(dep)) {
            for (const need of dep) if (!(need in instance)) errors.push(`dependency ${need}`);
          } else {
            validate(instance, dep, doc, base, depth + 1);
          }
        }
      }
      if (isNum(schema.minProperties) && Object.keys(instance).length < schema.minProperties) errors.push('minProperties');
      if (isNum(schema.maxProperties) && Object.keys(instance).length > schema.maxProperties) errors.push('maxProperties');
      if (isArr(schema.required)) {
        for (const r of schema.required) if (!(r in instance)) errors.push(`required ${r}`);
      }
    }
    if (isArr(instance)) {
      if (schema.items !== undefined) {
        if (isArr(schema.items)) instance.forEach((el, i) => { if (i < schema.items.length) validate(el, schema.items[i], doc, base, depth + 1); });
        else instance.forEach((el) => validate(el, schema.items, doc, base, depth + 1));
      }
      if (isNum(schema.minItems) && instance.length < schema.minItems) errors.push('minItems');
      if (isNum(schema.maxItems) && instance.length > schema.maxItems) errors.push('maxItems');
      if (schema.uniqueItems === true) {
        outer: for (let i = 0; i < instance.length; i++)
          for (let j = i + 1; j < instance.length; j++)
            if (pyEqual(instance[i], instance[j])) { errors.push('uniqueItems'); break outer; }
      }
    }
    if (isStr(instance)) {
      if (isNum(schema.minLength) && [...instance].length < schema.minLength) errors.push('minLength');
      if (isNum(schema.maxLength) && [...instance].length > schema.maxLength) errors.push('maxLength');
      if (isStr(schema.pattern) && !new RegExp(schema.pattern).test(instance)) errors.push('pattern');
    }
    if (isNum(instance)) {
      if (isNum(schema.minimum)) {
        const excl = schema.exclusiveMinimum;
        if (excl === true ? instance <= schema.minimum : instance < schema.minimum) errors.push('minimum');
      }
      if (isNum(schema.maximum)) {
        const excl = schema.exclusiveMaximum;
        if (excl === true ? instance >= schema.maximum : instance > schema.maximum) errors.push('maximum');
      }
      if (isNum(schema.exclusiveMinimum) && instance <= schema.exclusiveMinimum) errors.push('exclusiveMinimum');
      if (isNum(schema.exclusiveMaximum) && instance >= schema.exclusiveMaximum) errors.push('exclusiveMaximum');
      if (isNum(schema.multipleOf) && instance % schema.multipleOf !== 0) errors.push('multipleOf');
    }
    if (isArr(schema.allOf)) for (const sub of schema.allOf) validate(instance, sub, doc, base, depth + 1);
    if (isArr(schema.anyOf)) {
      const before = errors.length;
      const ok = schema.anyOf.some((sub) => { const saved = errors.length; validate(instance, sub, doc, base, depth + 1); const good = errors.length === saved; errors.length = saved; return good; });
      if (!ok) errors.push('anyOf');
      void before;
    }
    if (isArr(schema.oneOf)) {
      let count = 0;
      for (const sub of schema.oneOf) {
        const saved = errors.length;
        validate(instance, sub, doc, base, depth + 1);
        if (errors.length === saved) count++;
        errors.length = saved;
      }
      if (count !== 1) errors.push('oneOf');
    }
    if (schema.not !== undefined) {
      const saved = errors.length;
      validate(instance, schema.not, doc, base, depth + 1);
      const valid = errors.length === saved;
      errors.length = saved;
      if (valid) errors.push('not');
    }
  }

  const rootId = root.$id || root.id;
  validate.__rootBase = rootId;
  return {
    check(instance) {
      errors.length = 0;
      validate(instance, root, root, rootId, 0);
      return [...errors];
    },
  };
}

const metas = { d4: META4, d6: META6, d7: META7, d2019: META2019, d2020: META2020 };
const checkers = Object.fromEntries(Object.entries(metas).map(([k, m]) => [k, makeValidator(m)]));

const cases = [
  // [schema, expected validity per draft d4,d6,d7,d2019,d2020]
  [{ "type": "object", "properties": { "a": { "type": "string" } } }, [1, 1, 1, 1, 1]],
  [{ "type": 123 }, [0, 0, 0, 0, 0]],
  [{ "type": "bogus" }, [0, 0, 0, 0, 0]],
  [{ "type": ["string", 5] }, [0, 0, 0, 0, 0]],
  [{ "enum": [] }, [0, 0, 1, 1, 1]],
  [{ "exclusiveMinimum": true }, [1, 0, 0, 0, 0]],
  [{ "exclusiveMinimum": 5 }, [0, 1, 1, 1, 1]],
  [{ "minimum": 3, "exclusiveMinimum": true }, [1, 0, 0, 0, 0]],
  [{ "properties": 123 }, [0, 0, 0, 0, 0]],
  [{ "items": "foo" }, [0, 0, 0, 0, 0]],
  [{ "minLength": -1 }, [0, 0, 0, 0, 0]],
  [{ "required": [] }, [0, 1, 1, 1, 1]],
  [{ "required": ["a", "a"] }, [0, 0, 0, 0, 0]],
  [{ "multipleOf": 0 }, [0, 0, 0, 0, 0]],
  [{ "dependencies": { "a": ["b"] } }, [1, 1, 1, 1, 1]],
  [{ "dependencies": { "a": "b" } }, [0, 0, 0, 0, 0]],
  [{ "if": { "type": "string" }, "then": { "const": "x" } }, [1, 1, 1, 1, 1]],
  [{ "if": "nope" }, [1, 1, 0, 0, 0]],
  [{ "contains": { "type": "integer" } }, [1, 1, 1, 1, 1]],
  [{ "propertyNames": { "minLength": 2 } }, [1, 1, 1, 1, 1]],
  [{ "prefixItems": [{ "type": "string" }] }, [1, 1, 1, 1, 1]],
  [{ "$defs": { "a": { "type": "integer" } } }, [1, 1, 1, 1, 1]],
  [{ "allOf": [] }, [0, 0, 0, 0, 0]],
  [{ "unknownKeyword": { "whatever": true } }, [1, 1, 1, 1, 1]],
  [{ "patternProperties": { "^a": { "type": "string" } } }, [1, 1, 1, 1, 1]],
  [{ "items": [{ "type": "string" }] }, [1, 1, 1, 1, 1]],
  [{ "items": [{}] }, [0, 0, 0, 0, 0]],
  [{ "const": 42 }, [1, 1, 1, 1, 1]],
  [{ "minContains": 0 }, [1, 1, 1, 1, 1]],
  [{ "minContains": -1 }, [1, 1, 1, 0, 0]],
  [{ "maxContains": 1.5 }, [1, 1, 1, 0, 0]],
  [{ "format": 123 }, [1, 0, 0, 0, 0]],
  [{ "$ref": "#/definitions/x", "definitions": { "x": { "type": "string" } } }, [1, 1, 1, 1, 1]],
  [{ "title": 42 }, [0, 0, 0, 0, 0]],
  [{ "readOnly": "yes" }, [1, 1, 0, 0, 0]],
];

let failures = 0;
cases.forEach(([schema, expected], idx) => {
  const got = Object.values(checkers).map((c) => (c.check(schema).length === 0 ? 1 : 0));
  const bad = got.some((g, i) => g !== expected[i]);
  if (bad) {
    failures++;
    console.log(`FAIL case ${idx}: ${JSON.stringify(schema)}`);
    console.log(`  expected ${expected} got ${got}`);
    Object.entries(checkers).forEach(([k, c]) => {
      const errs = c.check(schema);
      if (errs.length) console.log(`    ${k}: ${errs.join('; ')}`);
    });
  }
});
console.log(failures === 0 ? `ALL ${cases.length} cases passed` : `${failures} cases FAILED`);
